import { LitElement, html, nothing } from 'lit';
import { styles } from './mas-quick-actions.css.js';
import { QUICK_ACTION } from './constants.js';

const ACTION_CONFIG = {
    [QUICK_ACTION.SAVE]: {
        icon: 'sp-icon-save-floppy',
        title: 'Save',
    },
    [QUICK_ACTION.DUPLICATE]: {
        icon: 'sp-icon-duplicate',
        title: 'Duplicate',
    },
    [QUICK_ACTION.PUBLISH]: {
        icon: 'sp-icon-publish',
        title: 'Publish',
    },
    [QUICK_ACTION.UNPUBLISH]: {
        icon: 'sp-icon-publish-remove',
        title: 'Unpublish',
    },
    [QUICK_ACTION.CANCEL]: {
        icon: 'sp-icon-undo',
        title: 'Cancel',
    },
    [QUICK_ACTION.COPY]: {
        icon: 'sp-icon-code',
        title: 'Copy code',
    },
    [QUICK_ACTION.LOCK]: {
        icon: 'sp-icon-lock-closed',
        title: 'Lock',
    },
    [QUICK_ACTION.DISCARD]: {
        icon: 'sp-icon-undo',
        title: 'Discard',
    },
    [QUICK_ACTION.DELETE]: {
        icon: 'sp-icon-delete',
        title: 'Delete',
        className: 'delete-action',
    },
    [QUICK_ACTION.LOC]: {
        icon: 'custom-icon-send-to-loc',
        title: 'Send to Localization',
    },
};

class MasQuickActions extends LitElement {
    static styles = styles;

    static properties = {
        isDraggable: { type: Boolean },
        actions: { type: Array },
        disabled: { type: Set },
        _dragging: { type: Boolean, state: true },
    };

    #posX = null;
    #posY = null;
    #startX = 0;
    #startY = 0;
    #initialX = 0;
    #initialY = 0;

    constructor() {
        super();
        this.isDraggable = true;
        this.actions = [];
        this.disabled = new Set();
        this._dragging = false;
    }

    #getEventCoordinates(e) {
        if (e.touches && e.touches.length > 0) {
            return { clientX: e.touches[0].clientX, clientY: e.touches[0].clientY };
        }
        return { clientX: e.clientX, clientY: e.clientY };
    }

    #handleDragStart(e) {
        if (!this.isDraggable) return;
        e.preventDefault();
        this._dragging = true;
        const { clientX, clientY } = this.#getEventCoordinates(e);
        this.#startX = clientX;
        this.#startY = clientY;
        const toolbar = this.shadowRoot?.querySelector('.quick-actions-toolbar');
        if (toolbar) {
            const rect = toolbar.getBoundingClientRect();
            this.#initialX = rect.left + rect.width / 2;
            this.#initialY = window.innerHeight - rect.bottom;
        }
        document.addEventListener('mousemove', this.#handleDrag);
        document.addEventListener('mouseup', this.#handleDragEnd);
        document.addEventListener('touchmove', this.#handleDrag, { passive: false });
        document.addEventListener('touchend', this.#handleDragEnd);
    }

    #handleDrag = (e) => {
        if (!this._dragging) return;
        e.preventDefault();
        const { clientX, clientY } = this.#getEventCoordinates(e);
        const deltaX = clientX - this.#startX;
        const deltaY = clientY - this.#startY;
        let newX = this.#initialX + deltaX;
        let newY = this.#initialY - deltaY;
        const toolbar = this.shadowRoot?.querySelector('.quick-actions-toolbar');
        if (toolbar) {
            const rect = toolbar.getBoundingClientRect();
            const halfWidth = rect.width / 2;
            const height = rect.height;
            newX = Math.max(halfWidth, Math.min(newX, window.innerWidth - halfWidth));
            newY = Math.max(0, Math.min(newY, window.innerHeight - height - 24));
        }
        this.#posX = newX;
        this.#posY = newY;
        this.requestUpdate();
    };

    #handleDragEnd = () => {
        this._dragging = false;
        document.removeEventListener('mousemove', this.#handleDrag);
        document.removeEventListener('mouseup', this.#handleDragEnd);
        document.removeEventListener('touchmove', this.#handleDrag);
        document.removeEventListener('touchend', this.#handleDragEnd);
    };

    disconnectedCallback() {
        super.disconnectedCallback();
        this.#handleDragEnd();
    }

    resetPosition() {
        this.#posX = null;
        this.#posY = null;
        this.requestUpdate();
    }

    get dragHandle() {
        if (!this.isDraggable) return nothing;
        return html`
            <div
                class="drag-handle"
                title="Drag to reposition"
                @mousedown=${(e) => this.#handleDragStart(e)}
                @touchstart=${(e) => this.#handleDragStart(e)}
            >
                <svg
                    id="Layer_1"
                    data-name="Layer 1"
                    xmlns="http://www.w3.org/2000/svg"
                    width="26"
                    height="26"
                    viewBox="0 0 18 18"
                >
                    <defs>
                        <style>
                            .fill {
                                fill: #464646;
                            }
                        </style>
                    </defs>

                    <rect id="Canvas" fill="#ff13dc" opacity="0" width="18" height="18" />

                    <circle class="fill" cx="7" cy="13" r="1" />
                    <circle class="fill" cx="7" cy="10" r="1" />
                    <circle class="fill" cx="7" cy="7" r="1" />
                    <circle class="fill" cx="7" cy="4" r="1" />

                    <circle class="fill" cx="10" cy="13" r="1" />
                    <circle class="fill" cx="10" cy="10" r="1" />
                    <circle class="fill" cx="10" cy="7" r="1" />
                    <circle class="fill" cx="10" cy="4" r="1" />
                </svg>
            </div>
        `;
    }

    get sendToLocIcon() {
        return html`<sp-icon slot="icon">
            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 20 20" fill="currentColor">
                <path
                    d="M19.0576 14.6934L11.0576 11.0977C10.8008 10.9815 10.502 11.0186 10.2813 11.1954C10.0615 11.3711 9.95901 11.6553 10.0147 11.9307L10.7217 15.3965L10.042 18.8555C9.98831 19.1309 10.0928 19.4141 10.3135 19.5879C10.4483 19.6954 10.6123 19.75 10.7783 19.75C10.8838 19.75 10.9893 19.7276 11.0889 19.6827L19.0606 16.0596C19.3281 15.9375 19.501 15.67 19.5 15.375C19.499 15.0811 19.3262 14.8135 19.0576 14.6934ZM15.5396 14.7564L12.1243 14.7666L11.7774 13.0655L15.5396 14.7564ZM12.1287 16.0166L15.5523 16.0064L11.7949 17.7139L12.1287 16.0166Z"
                    fill="currentColor"
                />
                <path
                    d="M7.54688 18H4.25C3.00977 18 2 16.9902 2 15.75V4.25C2 3.00977 3.00977 2 4.25 2H15.75C16.9902 2 18 3.00977 18 4.25V11.3965C18 11.8105 17.6641 12.1465 17.25 12.1465C16.8359 12.1465 16.5 11.8105 16.5 11.3965V4.25C16.5 3.83691 16.1631 3.5 15.75 3.5H4.25C3.83691 3.5 3.5 3.83691 3.5 4.25V15.75C3.5 16.1631 3.83691 16.5 4.25 16.5H7.54688C7.96094 16.5 8.29688 16.8359 8.29688 17.25C8.29688 17.6641 7.96094 18 7.54688 18Z"
                    fill="currentColor"
                />
                <path
                    d="M6.7627 9.5H5.7627C5.34864 9.5 5.0127 9.16406 5.0127 8.75C5.0127 8.33594 5.34864 8 5.7627 8H6.7627C7.17676 8 7.5127 8.33594 7.5127 8.75C7.5127 9.16406 7.17676 9.5 6.7627 9.5Z"
                    fill="currentColor"
                />
                <path
                    d="M14.2627 9.5H9.7627C9.34864 9.5 9.0127 9.16406 9.0127 8.75C9.0127 8.33594 9.34864 8 9.7627 8H14.2627C14.6768 8 15.0127 8.33594 15.0127 8.75C15.0127 9.16406 14.6768 9.5 14.2627 9.5Z"
                    fill="currentColor"
                />
                <path
                    d="M6.7627 6.5H5.7627C5.34864 6.5 5.0127 6.16406 5.0127 5.75C5.0127 5.33594 5.34864 5 5.7627 5H6.7627C7.17676 5 7.5127 5.33594 7.5127 5.75C7.5127 6.16406 7.17676 6.5 6.7627 6.5Z"
                    fill="currentColor"
                />
                <path
                    d="M14.2627 6.5H9.7627C9.34864 6.5 9.0127 6.16406 9.0127 5.75C9.0127 5.33594 9.34864 5 9.7627 5H14.2627C14.6768 5 15.0127 5.33594 15.0127 5.75C15.0127 6.16406 14.6768 6.5 14.2627 6.5Z"
                    fill="currentColor"
                />
                <path
                    d="M6.7627 12.5H5.7627C5.34864 12.5 5.0127 12.1641 5.0127 11.75C5.0127 11.3359 5.34864 11 5.7627 11H6.7627C7.17676 11 7.5127 11.3359 7.5127 11.75C7.5127 12.1641 7.17676 12.5 6.7627 12.5Z"
                    fill="currentColor"
                />
            </svg>
        </sp-icon>`;
    }

    renderIcon(iconName) {
        switch (iconName) {
            case 'sp-icon-save-floppy':
                return html`<sp-icon-save-floppy slot="icon"></sp-icon-save-floppy>`;
            case 'sp-icon-duplicate':
                return html`<sp-icon-duplicate slot="icon"></sp-icon-duplicate>`;
            case 'sp-icon-publish':
                return html`<sp-icon-publish slot="icon"></sp-icon-publish>`;
            case 'sp-icon-publish-remove':
                return html`<sp-icon-publish-remove slot="icon"></sp-icon-publish-remove>`;
            case 'sp-icon-code':
                return html`<sp-icon-code slot="icon"></sp-icon-code>`;
            case 'sp-icon-lock-closed':
                return html`<sp-icon-lock-closed slot="icon"></sp-icon-lock-closed>`;
            case 'sp-icon-undo':
                return html`<sp-icon-undo slot="icon"></sp-icon-undo>`;
            case 'sp-icon-delete':
                return html`<sp-icon-delete slot="icon"></sp-icon-delete>`;
            case 'custom-icon-send-to-loc':
                return this.sendToLocIcon;
            default:
                return nothing;
        }
    }

    renderAction(action) {
        const config = ACTION_CONFIG[action];
        if (!config) return nothing;
        return html`
            <sp-action-button
                class="${config.className || ''}"
                title="${config.title}"
                ?disabled=${this.disabled.has(action)}
                @click="${() => this.dispatchEvent(new CustomEvent(action, { bubbles: true, composed: true }))}"
            >
                ${this.renderIcon(config.icon)}
            </sp-action-button>
        `;
    }

    get #positionStyles() {
        if (!this.isDraggable || (this.#posX === null && this.#posY === null)) {
            return '';
        }
        const styles = [];
        if (this.#posX !== null) {
            styles.push(`left: ${this.#posX}px`);
            styles.push('transform: translateX(-50%)');
        }
        if (this.#posY !== null) {
            styles.push(`bottom: ${this.#posY}px`);
        }
        return styles.join('; ');
    }

    render() {
        const draggingClass = this._dragging ? 'dragging' : '';
        const positionStyle = this.#positionStyles;
        return html`
            <div class="quick-actions-toolbar ${draggingClass}" style="${positionStyle}">
                ${this.dragHandle}
                <div class="actions">${this.actions.map((action) => this.renderAction(action))}</div>
            </div>
        `;
    }
}

customElements.define('mas-quick-actions', MasQuickActions);

import { PATH_TOKENS, PZN_FOLDER, TAG_PROMOTION_PREFIX } from '../constants.js';

export class Fragment {
    path = '';
    hasChanges = false;
    status = '';

    fields = [];

    selected = false;

    initialValue;

    /**
     * @param {*} AEM Fragment JSON object
     */
    constructor(fragment) {
        this.refreshFrom(fragment);
    }

    getField(fieldName) {
        return this.fields.find((field) => field.name === fieldName);
    }

    getFieldValues(fieldName) {
        return this.getField(fieldName)?.values || [];
    }

    getFieldValue(fieldName, index = 0) {
        return this.getFieldValues(fieldName)?.[index];
    }

    isValueEmpty(values) {
        return values.length === 0 || values.every((v) => v === '' || v === null || v === undefined);
    }

    get variant() {
        return this.getFieldValue('variant');
    }

    get fragmentName() {
        return this.path.split('/').pop();
    }

    get statusVariant() {
        return this.status?.toLowerCase();
    }

    getTagTitle(id) {
        const tags = this.tags.filter((tag) => tag.id.includes(id));
        return tags[0]?.title;
    }

    get locale() {
        const match = this.path.match(PATH_TOKENS);
        return match?.groups?.parsedLocale || '';
    }

    /**
     * Updates the fragment entirely while preserving the initial value & hasChange status if not specified
     * @param {object} fragmentData
     * @param {Boolean | undefined} hasChanges
     */
    replaceFrom(fragmentData, hasChanges) {
        const clonedData = structuredClone(fragmentData);
        Object.assign(this, clonedData);
        if (hasChanges === undefined) return;
        this.hasChanges = hasChanges;
    }

    refreshFrom(fragmentData) {
        this.replaceFrom(fragmentData, false);
        this.initialValue = structuredClone(fragmentData);
        this.newTags = undefined;
    }

    discardChanges() {
        if (!this.hasChanges) return;
        this.newTags = undefined;
        this.replaceFrom(this.initialValue, false);
    }

    updateFieldInternal(fieldName, value) {
        this[fieldName] = value ?? '';
        this.hasChanges = true;
    }

    getVariations() {
        return this.getFieldValues('variations') || [];
    }

    hasVariations() {
        const variations = this.getVariations();
        return variations.length > 0;
    }

    /**
     * Updates a field's values.
     * For variations: if values match parent exactly, resets to inherited state.
     * @param {string} fieldName - The field name to update
     * @param {Array} value - The new values
     * @param {Fragment|null} [parentFragment] - The parent fragment (for variations)
     * @returns {boolean|'reset'} - true if updated, false if no change, 'reset' if reset to parent
     */
    updateField(fieldName, value, parentFragment = null) {
        const encodedValues = value.map((v) => (typeof v === 'string' ? v.normalize('NFC') : v));
        const existingField = this.getField(fieldName);
        const isTags = fieldName === 'tags';
        const parentField = parentFragment?.getField(fieldName);

        // [''] is the explicit clear sentinel for multi-value fields
        const isSingleEmptyString = encodedValues.length === 1 && encodedValues[0] === '';

        // Determine if this is a multi-value field based on the .multiple property
        const isMultiple = parentField?.multiple === true || existingField?.multiple === true;

        // For variations: if values match parent exactly, reset to inherited state
        if (parentFragment) {
            const parentValues = parentField?.values || [];
            const valuesMatchParent =
                encodedValues.length === parentValues.length && encodedValues.every((v, i) => v === parentValues[i]);

            if (valuesMatchParent) {
                // Reset field if it exists, or just confirm it should stay inherited
                this.resetFieldToParent(fieldName);
                return 'reset';
            }
        }

        if (existingField) {
            const { values } = existingField;
            // Skip [] to [''] on single-value fields (RTE initialization sends [''] for empty fields).
            // For multiple:true fields, [''] is an explicit "clear" sentinel.
            if (values.length === 0 && isSingleEmptyString && !isMultiple) {
                return false;
            }
            // No change if values are identical
            if (values.length === encodedValues.length && values.every((v, i) => v === encodedValues[i])) {
                if (isTags) this.newTags = value;
                return false;
            }
            existingField.values = encodedValues;
            // Inherit multiple from parent field if not already set
            if (parentField?.multiple && !existingField.multiple) {
                existingField.multiple = true;
            }
        } else {
            // Only create new field if there's meaningful content
            // Exception: [''] is allowed as explicit clear sentinel for multi-value fields
            const hasContent = encodedValues.length && encodedValues.some((v) => v?.trim?.());
            if (!hasContent && !(isSingleEmptyString && isMultiple)) {
                if (isTags) this.newTags = value;
                return false;
            }
            const newField = { name: fieldName, type: 'text', values: encodedValues };
            // Inherit multiple from parent field
            if (parentField?.multiple) newField.multiple = true;
            this.fields.push(newField);
        }

        this.hasChanges = true;
        if (isTags) this.newTags = value;
        return true;
    }

    getEffectiveFieldValue(fieldName, parentFragment, isVariation, index = 0) {
        const ownValue = this.getFieldValue(fieldName, index);
        if (ownValue !== undefined && ownValue !== null && ownValue !== '') {
            return ownValue;
        }
        if (!parentFragment || !isVariation) {
            return ownValue;
        }
        return parentFragment.getFieldValue(fieldName, index);
    }

    getEffectiveFieldValues(fieldName, parentFragment, isVariation) {
        const ownField = this.getField(fieldName);
        const ownValues = ownField?.values || [];

        // [] (empty array) = inherit from parent if variation
        if (ownValues.length === 0) {
            if (!parentFragment || !isVariation) {
                return [];
            }
            const parentField = parentFragment.getField(fieldName);
            return parentField?.values || [];
        }

        // For [""] (single empty string):
        // - For multi-value fields (multiple: true): explicit clear sentinel → return empty array
        // - For single-value fields (multiple: false): AEM initializes empty fields this way → inherit from parent
        const isSingleEmptyString = ownValues.length === 1 && ownValues[0] === '';
        if (isSingleEmptyString) {
            const isMultipleField = ownField?.multiple === true;
            if (isMultipleField) {
                // Explicit clear for multi-value fields
                return [];
            }
            // Single-value field with [""] - inherit from parent if variation
            if (!parentFragment || !isVariation) {
                return [];
            }
            const parentField = parentFragment.getField(fieldName);
            return parentField?.values || [];
        }

        // Has actual values - return them
        return ownValues;
    }

    getFieldState(fieldName, parentFragment, isVariation) {
        if (!isVariation || !parentFragment) {
            return 'no-parent';
        }
        const ownField = this.getField(fieldName);
        const ownValues = ownField?.values || [];
        const parentValues = parentFragment.getFieldValues(fieldName) || [];

        // [] (empty array) = inherited
        if (ownValues.length === 0) {
            return 'inherited';
        }

        // For [""] (single empty string):
        // - For multi-value fields (multiple: true): this is explicit clear sentinel → overridden
        // - For single-value fields (multiple: false): AEM initializes empty fields this way → inherited
        const isSingleEmptyString = ownValues.length === 1 && ownValues[0] === '';
        if (isSingleEmptyString) {
            const isMultipleField = ownField?.multiple === true;
            if (!isMultipleField) {
                return 'inherited';
            }
            // For multiple fields, [""] is explicit clear - fall through to comparison
        }

        // Has actual values - compare with parent
        const normalizeForComparison = (v) => {
            if (v === null || v === undefined) return '';
            if (typeof v === 'string') {
                return v
                    .normalize('NFC')
                    .trim()
                    .replace(/\s+role="[^"]*"/g, '')
                    .replace(/\s+aria-level="[^"]*"/g, '');
            }
            return String(v);
        };

        const areEqual =
            ownValues.length === parentValues.length &&
            ownValues.every((v, i) => normalizeForComparison(v) === normalizeForComparison(parentValues[i]));

        return areEqual ? 'same-as-parent' : 'overridden';
    }

    isFieldOverridden(fieldName, parentFragment, isVariation) {
        return this.getFieldState(fieldName, parentFragment, isVariation) === 'overridden';
    }

    /**
     * Prepares a variation fragment for saving by resetting fields that match parent values.
     * This ensures we don't save inherited values as explicit overrides.
     * @param {Fragment} parentFragment - The parent fragment to compare against
     * @returns {Fragment} A clone of this fragment with inherited fields reset to []
     */
    prepareVariationForSave(parentFragment) {
        if (!parentFragment) return this;

        // Create a new Fragment instance from this fragment's data (constructor handles cloning)
        const prepared = new Fragment(this);

        // Fields that should never be reset (they're fragment-specific, not inherited)
        const excludeFields = ['variations', 'tags', 'originalId', 'locReady'];

        for (const field of prepared.fields) {
            if (excludeFields.includes(field.name)) continue;

            const fieldState = this.getFieldState(field.name, parentFragment, true);

            // If field is inherited or same-as-parent, reset to empty array
            // Only keep values that are truly overridden (different from parent)
            if (fieldState === 'inherited' || fieldState === 'same-as-parent') {
                field.values = [];
            }
        }

        return prepared;
    }

    resetFieldToParent(fieldName) {
        const fieldIndex = this.fields.findIndex((field) => field.name === fieldName);
        if (fieldIndex !== -1) {
            this.fields.splice(fieldIndex, 1);
            this.hasChanges = true;
            return true;
        }
        return false;
    }

    /**
     * Checks whether a path is a grouped (pzn) variation path.
     * @param {string} path
     * @returns {boolean}
     */
    static isGroupedVariationPath(path) {
        return path?.includes(`/${PZN_FOLDER}/`) ?? false;
    }

    /**
     * Categorizes all variation references in a single pass into locale, promo, and grouped buckets.
     * Each variation is classified into exactly one category (grouped > promo > locale).
     * @returns {{ locale: Object[], promo: Object[], grouped: Object[] }}
     */
    #categorizeVariations() {
        const variationPaths = this.getVariations();
        if (!variationPaths.length || !this.references?.length) {
            return { locale: [], promo: [], grouped: [] };
        }

        const referencesByPath = new Map(this.references.map((ref) => [ref.path, ref]));

        const currentMatch = this.path.match(PATH_TOKENS);
        const { surface, parsedLocale: currentLocale, fragmentPath } = currentMatch?.groups || {};

        const locale = [];
        const promo = [];
        const grouped = [];

        for (const path of variationPaths) {
            const reference = referencesByPath.get(path);
            if (!reference) continue;

            if (Fragment.isGroupedVariationPath(path)) {
                grouped.push(reference);
                continue;
            }

            const isPromo = reference.tags?.some((t) => t.id?.startsWith(TAG_PROMOTION_PREFIX));
            if (isPromo) {
                promo.push(reference);
                continue;
            }

            if (surface && currentLocale && fragmentPath) {
                const refMatch = path.match(PATH_TOKENS);
                if (refMatch?.groups) {
                    const r = refMatch.groups;
                    if (r.surface === surface && r.fragmentPath === fragmentPath && r.parsedLocale !== currentLocale) {
                        locale.push(reference);
                    }
                }
            }
        }

        return { locale, promo, grouped };
    }

    /**
     * Lists all locale variations of the fragment (regional variations).
     * @returns {Object[]}
     */
    listLocaleVariations() {
        return this.#categorizeVariations().locale;
    }

    /**
     * Lists all grouped (pzn) variations of the fragment.
     * @returns {Object[]}
     */
    listGroupedVariations() {
        return this.#categorizeVariations().grouped;
    }

    /**
     * Gets the count of grouped (pzn) variations.
     * @returns {number}
     */
    getGroupedVariationCount() {
        return this.#categorizeVariations().grouped.length;
    }

    /**
     * Gets the count of locale variations.
     * @returns {number}
     */
    getLocaleVariationCount() {
        return this.#categorizeVariations().locale.length;
    }

    /**
     * Gets the count of promo variations.
     * @returns {number}
     */
    getPromoVariationCount() {
        return this.#categorizeVariations().promo.length;
    }

    /**
     * Gets the total count of all variations (locale + promo + grouped).
     * @returns {number}
     */
    getTotalVariationCount() {
        const { locale, promo, grouped } = this.#categorizeVariations();
        return locale.length + promo.length + grouped.length;
    }
}

import { LitElement, html, nothing } from 'lit';
import { repeat } from 'lit/directives/repeat.js';
import StoreController from './reactivity/store-controller.js';
import { VARIANTS } from './editors/variant-picker.js';
import Store from './store.js';
import './mas-fragment.js';
import Events from './events.js';
import { CARD_MODEL_PATH } from './constants.js';

const variantValues = VARIANTS.map((v) => v.value);
class MasContent extends LitElement {
    createRenderRoot() {
        return this;
    }

    constructor() {
        super();
        this.goToFragment = this.goToFragment.bind(this);
        this.subscriptions = [];
    }

    loading = new StoreController(this, Store.fragments.list.loading);
    firstPageLoaded = new StoreController(this, Store.fragments.list.firstPageLoaded);
    fragments = new StoreController(this, Store.fragments.list.data);
    renderMode = new StoreController(this, Store.renderMode);
    selecting = new StoreController(this, Store.selecting);
    selection = new StoreController(this, Store.selection);

    connectedCallback() {
        super.connectedCallback();
        Events.fragmentAdded.subscribe(this.goToFragment);
        Events.fragmentDeleted.subscribe(this.onFragmentDeleted);

        this.subscriptions.push(
            Store.fragments.list.data.subscribe(() => {
                this.requestUpdate();
            }),
        );

        this.subscriptions.push(
            Store.filters.subscribe(() => {
                this.requestUpdate();
            }),
        );
    }

    disconnectedCallback() {
        super.disconnectedCallback();
        Events.fragmentAdded.unsubscribe(this.goToFragment);
        Events.fragmentDeleted.unsubscribe(this.onFragmentDeleted);

        if (this.subscriptions && this.subscriptions.length) {
            this.subscriptions.forEach((subscription) => {
                if (subscription) {
                    subscription.unsubscribe();
                }
            });
        }
        this.subscriptions = [];
    }

    onFragmentDeleted(fragment) {
        Store.fragments.list.data.set((prev) => {
            const result = [...prev];
            const index = result.findIndex((fragmentStore) => fragmentStore.get().id === fragment.id);
            if (index !== -1) {
                result.splice(index, 1);
            }
            return result;
        });
        Store.fragments.inEdit.set(null);
    }

    async goToFragment(id, skipUpdate = false) {
        if (!skipUpdate) await this.updateComplete;

        const fragmentElement = document.querySelector(`.mas-fragment[data-id="${id}"]`);
        if (!fragmentElement) return;

        fragmentElement.scrollIntoView({ behavior: 'smooth' });
    }

    get renderView() {
        return html`
            <div id="render">
                ${repeat(
                    this.fragments.value.filter((fragmentStore) => {
                        const value = fragmentStore.get();
                        if (!value) return false;
                        if (fragmentStore.new) return true;
                        if (value.model?.path === CARD_MODEL_PATH && !variantValues.includes(fragmentStore.value.variant))
                            return false;
                        return true;
                    }),
                    (fragmentStore) => fragmentStore.get()?.path || fragmentStore.id || Math.random(),
                    (fragmentStore) => html`<mas-fragment .fragmentStore=${fragmentStore} view="render"></mas-fragment>`,
                )}
            </div>
        `;
    }

    updateTableSelection(event) {
        Store.selection.set(Array.from(event.target.selectedSet));
    }

    get tableView() {
        return html`<sp-table
            emphasized
            scroller
            selects=${this.selecting.value ? 'multiple' : undefined}
            selected=${JSON.stringify(this.selection.value)}
            @change=${this.updateTableSelection}
        >
            <sp-table-head>
                <sp-table-head-cell class="expand-cell"></sp-table-head-cell>
                <sp-table-head-cell sortable class="name">Path</sp-table-head-cell>
                <sp-table-head-cell sortable class="title">Fragment Title</sp-table-head-cell>
                <sp-table-head-cell sortable class="offer-id">Offer ID</sp-table-head-cell>
                <sp-table-head-cell sortable class="offer-type">Offer Type</sp-table-head-cell>
                <sp-table-head-cell sortable class="last-modified-by">Last Modified By</sp-table-head-cell>
                <sp-table-head-cell sortable class="price">Price</sp-table-head-cell>
                <sp-table-head-cell sortable class="status">Status</sp-table-head-cell>
                <sp-table-head-cell class="actions">Actions</sp-table-head-cell>
                <sp-table-head-cell class="preview">Preview</sp-table-head-cell>
            </sp-table-head>
            <sp-table-body>
                ${repeat(
                    this.fragments.value.filter((fragmentStore) => fragmentStore.get() !== null),
                    (fragmentStore) => fragmentStore.get().path,
                    (fragmentStore) => html`<mas-fragment .fragmentStore=${fragmentStore} view="table"></mas-fragment>`,
                )}
            </sp-table-body>
        </sp-table>`;
    }

    /** main spinner to show while loading the first page */
    get firstPageLoadingSpinner() {
        if (!this.loading.value || this.firstPageLoaded.value) return nothing;
        return html`<sp-progress-circle class="fragments" indeterminate size="l"></sp-progress-circle>`;
    }

    /** spinner to show at the bottom of the page if next page is being loaded */
    get pageLoadingSpinner() {
        if (!this.loading.value || !this.firstPageLoaded.value) return nothing;
        return html`<sp-progress-circle class="next-page" indeterminate size="l"></sp-progress-circle>`;
    }

    render() {
        let view = nothing;
        switch (this.renderMode.value) {
            case 'render':
                view = this.renderView;
                break;
            case 'table':
                view = this.tableView;
                break;
            default:
                view = this.renderView;
        }
        return html`<div id="content">${view} ${this.firstPageLoadingSpinner}</div>
            ${this.pageLoadingSpinner}`;
    }
}

